// Serve mode: one process serves the site and keeps it up to date, so the
// whole dashboard runs as a single container behind a reverse proxy.
//
//	GET  /              page files, compiled in (site.Files) or from -site
//	GET  /stats.json    generated by the last sync (dir of -out)
//	GET  /photos/…      published meal photos (dir of -out)
//	GET  /routes/…      workout GPS tracks (dir of -out)
//	GET  /days/…        the older days, one file per year (dir of -out)
//	GET  /healthz       200 while syncs succeed, 503 when the data is stale
//	GET  /api/status    sync state; needs the admin token
//	POST /api/sync      starts a sync now (?all=1 re-fetches the whole window); needs the admin token
//
// The /api endpoints only exist when ADMIN_TOKEN is set. The token is sent as
// "Authorization: Bearer <token>".

type serveOptions struct {
	addr       string
	interval   time.Duration
	siteDir    string // "" serves the compiled-in page files
	adminToken string
}

// csp matches the <meta> policy in index.html; as a header it can also forbid
// framing, which a <meta> policy cannot.
const csp = "default-src 'none'; script-src 'self'; style-src 'self'; img-src 'self' data: https://tile.openstreetmap.org; font-src 'self'; " +
	"connect-src 'self'; manifest-src 'self'; worker-src 'self'; base-uri 'none'; form-action 'none'; frame-ancestors 'none'"

const (
	minInterval = 5 * time.Minute  // Yazio's API is private; don't hammer it
	syncTimeout = 15 * time.Minute // a full backfill with photos takes a few minutes
)

func serve(ctx context.Context, cfg config, o serveOptions) error {
	if o.interval < minInterval {
		return fmt.Errorf("-interval %s is too short, use at least %s", o.interval, minInterval)
	}
	pages, from := fs.FS(site.Files), "compiled-in page files"
	if o.siteDir != "" {
		pages, from = os.DirFS(o.siteDir), o.siteDir
	}
	if _, err := fs.Stat(pages, "index.html"); err != nil {
		return fmt.Errorf("%s have no index.html: %w", from, err)
	}
	if o.adminToken == "" {
		log.Printf("ADMIN_TOKEN is not set: the refresh button and /api are disabled")
	}

	r := newRunner(cfg, o.interval)
	srv := &http.Server{
		Addr:              o.addr,
		Handler:           newHandler(r, pages, filepath.Dir(cfg.outPath), o.adminToken),
		ReadHeaderTimeout: 10 * time.Second,
		ReadTimeout:       30 * time.Second,
		WriteTimeout:      60 * time.Second,
		IdleTimeout:       120 * time.Second,
		MaxHeaderBytes:    16 << 10,
	}

	go r.schedule(ctx)

	errc := make(chan error, 1)
	go func() {
		log.Printf("serving %s on %s, syncing every %s", from, o.addr, o.interval)
		errc <- srv.ListenAndServe()
	}()
	select {
	case err := <-errc:
		return err
	case <-ctx.Done():
	}
	log.Printf("shutting down")
	shutdownCtx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()
	if err := srv.Shutdown(shutdownCtx); err != nil {
		return err
	}
	r.wait()
	return nil
}

// runner runs syncs one at a time, on a schedule or on request.
type runner struct {
	cfg      config
	interval time.Duration
	started  time.Time
	sync     func(context.Context, config) error // syncOnce; replaced in tests

	mu          sync.Mutex
	running     bool
	runningAll  bool // the running sync re-fetches everything
	lastAttempt time.Time
	lastSuccess time.Time
	lastError   string
	wg          sync.WaitGroup
}

func newRunner(cfg config, interval time.Duration) *runner {
	return &runner{cfg: cfg, interval: interval, started: time.Now(), sync: syncOnce}
}

// schedule syncs right away and then every interval until ctx ends. A
// refresh-all request (flag or YAZIO_REFRESH_ALL) only applies to the first
// sync; otherwise every scheduled run would re-fetch a whole year.
func (r *runner) schedule(ctx context.Context) {
	r.start(ctx, r.cfg.refreshAll)
	t := time.NewTicker(r.interval)
	defer t.Stop()
	for {
		select {
		case <-ctx.Done():
			return
		case <-t.C:
			r.start(ctx, false)
		}
	}
}

// start begins a sync in the background and reports false if one is already
// running.
func (r *runner) start(ctx context.Context, refreshAll bool) bool {
	r.mu.Lock()
	defer r.mu.Unlock()
	if r.running {
		return false
	}
	r.running, r.runningAll = true, refreshAll
	r.lastAttempt = time.Now()
	r.wg.Add(1)
	go func() {
		defer r.wg.Done()
		cfg := r.cfg
		cfg.refreshAll = refreshAll
		syncCtx, cancel := context.WithTimeout(ctx, syncTimeout)
		err := r.sync(syncCtx, cfg)
		cancel()

		r.mu.Lock()
		defer r.mu.Unlock()
		r.running, r.runningAll = false, false
		if err != nil {
			r.lastError = err.Error()
			log.Printf("sync failed: %v", err)
		} else {
			r.lastError = ""
			r.lastSuccess = time.Now()
		}
	}()
	return true
}

func (r *runner) wait() { r.wg.Wait() }

type syncStatus struct {
	Running bool `json:"running"`
	// All marks a running refresh of the whole history.
	All bool `json:"all,omitempty"`
	// RefreshDays is how many recent days a normal sync re-fetches.
	RefreshDays int        `json:"refresh_days"`
	LastAttempt *time.Time `json:"last_attempt,omitempty"`
	LastSuccess *time.Time `json:"last_success,omitempty"`
	LastError   string     `json:"last_error,omitempty"`
	Interval    string     `json:"interval"`
}

func (r *runner) status() syncStatus {
	r.mu.Lock()
	defer r.mu.Unlock()
	opt := func(t time.Time) *time.Time {
		if t.IsZero() {
			return nil
		}
		return &t
	}
	return syncStatus{
		Running:     r.running,
		All:         r.runningAll,
		RefreshDays: r.cfg.refreshDays,
		LastAttempt: opt(r.lastAttempt),
		LastSuccess: opt(r.lastSuccess),
		LastError:   r.lastError,
		Interval:    r.interval.String(),
	}
}

// healthy reports whether a sync succeeded within the last three intervals
// (or the server is younger than that and still catching up).
func (r *runner) healthy(now time.Time) bool {
	r.mu.Lock()
	defer r.mu.Unlock()
	last := r.lastSuccess
	if last.IsZero() {
		last = r.started
	}
	return now.Sub(last) < 3*r.interval
}

func newHandler(r *runner, pages fs.FS, publicDir, adminToken string) http.Handler {
	site := http.FileServerFS(noDirs{pages})
	tags := etags(pages)
	public := http.FileServerFS(noDirs{os.DirFS(publicDir)})
	auth := newAuth(adminToken)

	mux := http.NewServeMux()
	mux.HandleFunc("GET /healthz", func(w http.ResponseWriter, req *http.Request) {
		w.Header().Set("Cache-Control", "no-store")
		if !r.healthy(time.Now()) {
			http.Error(w, "stale", http.StatusServiceUnavailable)
			return
		}
		fmt.Fprintln(w, "ok")
	})
	if adminToken != "" {
		mux.Handle("GET /api/status", auth.require(func(w http.ResponseWriter, req *http.Request) {
			writeJSON(w, http.StatusOK, r.status())
		}))
		mux.Handle("POST /api/sync", auth.require(func(w http.ResponseWriter, req *http.Request) {
			code := http.StatusAccepted
			if !r.start(context.WithoutCancel(req.Context()), req.URL.Query().Get("all") == "1") {
				code = http.StatusConflict
			}
			writeJSON(w, code, r.status())
		}))
	}
	mux.HandleFunc("GET /stats.json", func(w http.ResponseWriter, req *http.Request) {
		w.Header().Set("Cache-Control", "no-cache")
		public.ServeHTTP(w, req)
	})
	// Photo, route and archive names are content hashes: the same name never changes.
	immutable := func(w http.ResponseWriter, req *http.Request) {
		w.Header().Set("Cache-Control", "public, max-age=31536000, immutable")
		public.ServeHTTP(w, req)
	}
	mux.HandleFunc("GET /photos/", immutable)
	mux.HandleFunc("GET /routes/", immutable)
	mux.HandleFunc("GET /days/", immutable)
	mux.HandleFunc("GET /", func(w http.ResponseWriter, req *http.Request) {
		if strings.HasPrefix(req.URL.Path, "/fonts/") || strings.HasPrefix(req.URL.Path, "/icons/") {
			w.Header().Set("Cache-Control", "public, max-age=604800")
		} else {
			// Page code: revalidate every time, so a new image shows up at once.
			w.Header().Set("Cache-Control", "no-cache")
		}
		if tag, ok := tags[strings.TrimPrefix(path.Clean(req.URL.Path), "/")]; ok {
			w.Header().Set("ETag", tag)
		}
		site.ServeHTTP(w, req)
	})
	return securityHeaders(mux)
}

func securityHeaders(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, req *http.Request) {
		h := w.Header()
		h.Set("Content-Security-Policy", csp)
		h.Set("X-Content-Type-Options", "nosniff")
		h.Set("Referrer-Policy", "no-referrer")
		h.Set("X-Robots-Tag", "noindex, nofollow, noimageindex, noarchive")
		h.Set("Cross-Origin-Opener-Policy", "same-origin")
		h.Set("Permissions-Policy", "camera=(), microphone=(), geolocation=(), interest-cohort=()")
		next.ServeHTTP(w, req)
	})
}

// noDirs hides directories (except the root, which serves index.html), so
// the photo folder can't be listed.
// etags returns a content hash per file of compiled-in page files. They have
// no modification time, so without an ETag a browser couldn't revalidate
// them and would download every file again on each visit. Files on disk
// (-site) get Last-Modified instead and need none.
func etags(pages fs.FS) map[string]string {
	if pages != fs.FS(site.Files) {
		return nil
	}
	tags := map[string]string{}
	_ = fs.WalkDir(pages, ".", func(p string, d fs.DirEntry, err error) error {
		if err != nil || d.IsDir() {
			return err
		}
		data, err := fs.ReadFile(pages, p)
		if err != nil {
			return err
		}
		sum := sha256.Sum256(data)
		tags[p] = `"` + hex.EncodeToString(sum[:8]) + `"`
		return nil
	})
	tags[""] = tags["index.html"] // "/" serves index.html
	return tags
}

type noDirs struct{ fs.FS }

func (n noDirs) Open(name string) (fs.File, error) {
	f, err := n.FS.Open(name)
	if err != nil || name == "." {
		return f, err
	}
	info, err := f.Stat()
	if err != nil {
		f.Close()
		return nil, err
	}
	if info.IsDir() {
		f.Close()
		return nil, fs.ErrNotExist
	}
	return f, nil
}

// auth checks the admin token. After too many wrong tokens it refuses every
// attempt for a while, which makes guessing hopeless even without the
// reverse proxy's own rate limit.
type auth struct {
	want [32]byte

	mu       sync.Mutex
	failures int
	window   time.Time
}

const (
	maxFailures   = 5
	failureWindow = time.Minute
)

func newAuth(token string) *auth { return &auth{want: sha256.Sum256([]byte(token))} }

func (a *auth) require(next http.HandlerFunc) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, req *http.Request) {
		w.Header().Set("Cache-Control", "no-store")
		if a.locked(time.Now()) {
			http.Error(w, "too many attempts, try again in a minute", http.StatusTooManyRequests)
			return
		}
		token, ok := strings.CutPrefix(req.Header.Get("Authorization"), "Bearer ")
		got := sha256.Sum256([]byte(token))
		if !ok || subtle.ConstantTimeCompare(got[:], a.want[:]) != 1 {
			a.fail(time.Now())
			log.Printf("api: rejected token from %s", clientIP(req))
			http.Error(w, "unauthorized", http.StatusUnauthorized)
			return
		}
		next(w, req)
	})
}

func (a *auth) locked(now time.Time) bool {
	a.mu.Lock()
	defer a.mu.Unlock()
	if now.Sub(a.window) > failureWindow {
		a.failures, a.window = 0, now
	}
	return a.failures >= maxFailures
}

func (a *auth) fail(now time.Time) {
	a.mu.Lock()
	defer a.mu.Unlock()
	if now.Sub(a.window) > failureWindow {
		a.failures, a.window = 0, now
	}
	a.failures++
}

// clientIP is only used for logging; behind nginx the peer is always
// 127.0.0.1, so prefer the address nginx reports.
func clientIP(req *http.Request) string {
	if ip := req.Header.Get("X-Real-IP"); ip != "" {
		return ip
	}
	return req.RemoteAddr
}

func writeJSON(w http.ResponseWriter, code int, v any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(code)
	json.NewEncoder(w).Encode(v)
}

// healthcheck is the container's HEALTHCHECK: distroless images have no curl.
func healthcheck(url string) error {
	c := &http.Client{Timeout: 5 * time.Second}
	res, err := c.Get(url)
	if err != nil {
		return err
	}
	res.Body.Close()
	if res.StatusCode != http.StatusOK {
		return errors.New(res.Status)
	}
	return nil
}
